import{_ as o}from"./chunks/settings-robot.pc.ko.CimpdZDI.js";import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.D47SInms.js";const m=JSON.parse('{"title":"3. Payload 설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/payload-setting.md","filePath":"ko/guides/add-on/payload-setting.md","lastUpdated":1791600043000}'),n={name:"ko/guides/add-on/payload-setting.md"};function s(l,t,i,g,c,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_3-payload-설정" tabindex="-1">3. Payload 설정 <a class="header-anchor" href="#_3-payload-설정" aria-label="Permalink to &quot;3. Payload 설정&quot;">​</a></h1><p><strong>목표:</strong> RBQ 앱에서 추가 모듈의 <strong>질량</strong>과 <strong>무게중심 X/Y/Z</strong>를 등록하여, 로봇이 보행 중 이를 반영하도록 설정합니다.</p><p><strong>사전 조건:</strong> 2단계 <a href="/RBQ/nightly/ko/guides/add-on/rail-spring-nut.html">레일 &amp; 스프링 너트</a> 완료 — 추가 모듈이 레일에 물리적으로 장착되어 있어야 합니다.</p><h2 id="시작하기-전에" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#시작하기-전에" aria-label="Permalink to &quot;시작하기 전에&quot;">​</a></h2><ul><li>로봇을 <strong>평탄하고 안전한 바닥</strong>에 놓으세요.</li><li>RBQ 앱이 로봇에 <strong>연결</strong>되어 있어야 합니다 (<a href="/RBQ/nightly/ko/guides/common/controller-wifi-connect.html">컨트롤러 &amp; Wi-Fi</a> 완료).</li><li>추가 모듈 무게중심의 <strong>X / Y / Z</strong>(m)를 로봇 본체 중심 기준으로 측정해 두세요.</li></ul><h2 id="절차" tabindex="-1">절차 <a class="header-anchor" href="#절차" aria-label="Permalink to &quot;절차&quot;">​</a></h2><ol><li>앱에서 <strong>설정 › 페이로드 설정</strong>을 엽니다. <code>로봇 페이로드 설정</code> 화면이 나옵니다.</li></ol><figure style="text-align:center;"><img src="'+o+'" alt="로봇 파라미터 — 로봇 페이로드 설정" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">설정 › 페이로드 설정</figcaption></figure><ol start="2"><li><p>오른쪽 <strong>슬롯 표</strong>에서 등록할 슬롯을 누르고 <strong>체크박스를 켭니다.</strong> 체크를 켜면 로봇이 가진 카탈로그 기본값이 채워집니다.</p></li><li><p>왼쪽 <strong>편집창</strong>에 값을 넣습니다:</p><ul><li><strong>Mass (kg)</strong> — 추가 모듈 질량</li><li><strong>X / Y / Z (m)</strong> — 로봇 좌표계 기준 무게중심 위치</li></ul><p>칸을 눌러 직접 치거나 <code>−</code> · <code>+</code> 로 조절하며, <strong>간격</strong>(<code>0.001</code> · <code>0.01</code> · <code>0.1</code> · <code>1</code>)으로 한 번에 움직이는 양을 정합니다.</p></li><li><p>편집창 아래 <strong>합계</strong>에서 전체 질량과 합성 무게중심을 확인합니다. 상한을 넘으면 빨갛게 표시되고 전송되지 않습니다.</p></li><li><p><strong>Set Payload</strong>를 누르고 확인 창에서 <strong>적용</strong>을 눌러 로봇에 반영합니다. 체크 해제한 슬롯은 질량 0으로 전송되어 비워집니다.</p></li><li><p>적용 후 <strong>Get</strong>을 누르면 로봇에 저장된 값을 다시 읽어 확인할 수 있습니다.</p></li></ol><h2 id="버튼-설명" tabindex="-1">버튼 설명 <a class="header-anchor" href="#버튼-설명" aria-label="Permalink to &quot;버튼 설명&quot;">​</a></h2><table tabindex="0"><thead><tr><th>버튼</th><th>기능</th></tr></thead><tbody><tr><td><strong>체크박스</strong></td><td>그 슬롯을 장착 상태로 표시 (해제하면 전송 시 질량 0으로 비워짐)</td></tr><tr><td><strong>간격</strong></td><td><code>−</code> · <code>+</code> 한 번에 움직이는 양 (<code>0.001</code> · <code>0.01</code> · <code>0.1</code> · <code>1</code>)</td></tr><tr><td><strong>Set Payload</strong></td><td>편집한 슬롯 전체를 로봇에 적용 (확인 창을 거침)</td></tr><tr><td><strong>Get</strong></td><td>로봇에 저장된 값을 다시 읽어옴 — 편집 중이던 값은 버려짐</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>Payload 등록만으로는 충분하지 않습니다 — 다음 단계의 ZMP 캘리브레이션을 통해 새로운 하중 조건에서 균형을 맞추는 자세 보정이 함께 필요합니다.</p></div></div><p>허용 범위와 오류 메시지는 <a href="/RBQ/nightly/ko/manual/troubleshooting/payload_setting.html">페이로드 설정</a>에 정리되어 있습니다.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>Payload 등록이 끝났다면 새로운 무게 조건에서 균형을 맞추기 위해 ZMP 캘리브레이션을 수행합니다:</p><p><strong><a href="/RBQ/nightly/ko/guides/add-on/zmp-calibration.html">→ 4. ZMP 캘리브레이션</a></strong></p>',16)])])}const _=a(n,[["render",s]]);export{m as __pageData,_ as default};
